import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Releasing kiwa","description":"","frontmatter":{},"headers":[],"relativePath":"RELEASING.md","filePath":"RELEASING.md"}'),o={name:"RELEASING.md"};function n(r,e,l,c,h,d){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="releasing-kiwa" tabindex="-1">Releasing kiwa <a class="header-anchor" href="#releasing-kiwa" aria-label="Permalink to &quot;Releasing kiwa&quot;">​</a></h1><blockquote><p><a href="./RELEASING">🇬🇧 English</a> • <a href="./RELEASING.ja">🇯🇵 日本語</a></p></blockquote><p>kiwa releases are managed with Changesets and GitHub Actions. In this repository, version updates, <code>CHANGELOG.md</code> updates, and npm publishing are handled by a workflow that runs after merging to <code>main</code>. Local work stops at adding a changeset file, and version bumps and publishing are delegated to <code>release.yml</code>.</p><h2 id="changesets-workflow" tabindex="-1">Changesets workflow <a class="header-anchor" href="#changesets-workflow" aria-label="Permalink to &quot;Changesets workflow&quot;">​</a></h2><ol><li>In the PR that contains your changes, run <code>pnpm changeset</code> and add <code>.changeset/{name}.md</code>.</li><li>Merge the PR into <code>main</code>.</li><li><code>release.yml</code> starts, and the Changesets bot creates a <code>chore(release): version packages</code> PR.</li><li>The version PR includes package version bumps and <code>CHANGELOG.md</code> updates aggregated from pending changesets.</li><li>When the version PR is merged, <code>pnpm release</code> runs and publishes to npm with <code>pnpm publish -r --access public --provenance</code>.</li></ol><p>Before opening a PR, run <code>pnpm changeset</code> for any change that requires one. Then, always pass the following three commands as local verification.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Normally, do not use <code>pnpm version-packages</code> locally. Instead, review the diff in the version PR created by the Changesets bot. Only proceed with manual version bumps if you are temporarily changing the release operation.</p><h2 id="configuring-npm-token" tabindex="-1">Configuring NPM_TOKEN <a class="header-anchor" href="#configuring-npm-token" aria-label="Permalink to &quot;Configuring NPM_TOKEN&quot;">​</a></h2><p>Create an Automation Token on the npm side and register it in GitHub at <code>Settings &gt; Secrets and variables &gt; Actions</code> with the name <code>NPM_TOKEN</code>. The release workflow uses this secret to publish, so make sure it is configured before publishing. Use an Automation Token dedicated to publishing. The policy is not to use a regular personal account token.</p><h2 id="about-provenance" tabindex="-1">About provenance <a class="header-anchor" href="#about-provenance" aria-label="Permalink to &quot;About provenance&quot;">​</a></h2><p>Publishing with <code>--provenance</code> generates sigstore provenance using the GitHub Actions OIDC token. On the package page on npmjs.com, you can verify the linkage to the source repository and build workflow. To enable this, the release workflow always grants <code>permissions.id-token: write</code>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li>If a version PR is not created, check whether there is a pending changeset on <code>main</code>.</li><li>If publishing stops, check the <code>NPM_TOKEN</code> secret and workflow permissions.</li><li>If you want to inspect the tarball contents, run <code>npm pack --dry-run</code> in each package.</li></ul><h2 id="sha-pin-policy" tabindex="-1">SHA pin policy <a class="header-anchor" href="#sha-pin-policy" aria-label="Permalink to &quot;SHA pin policy&quot;">​</a></h2><p>Dependabot monitors the <code>github-actions</code> ecosystem daily and, through the <code>groups</code> setting, proposes all actions together in a single PR. The policy is to merge those PRs in a weekly batch. In particular, we recommend manual review for minor version updates of <code>changesets/action</code> because they carry a risk of internal behavior changes. SHA pinning prevents supply chain attacks through mutable major tags such as <code>@v4</code> and lets you update each action intentionally.</p><p>The routine group (<code>actions/*</code> + <code>pnpm/*</code>) also follows the same manual review policy for major updates, and <code>dependabot.yml</code> is configured with <code>ignore</code> to reject <code>version-update:semver-major</code>. Automatic PRs are limited to minor and patch updates. When a major update is required, open a SHA pin update PR after manual review (the SHA verification procedure is a two-step check: <code>gh api repos/{owner}/{repo}/git/refs/tags/v{version}</code> → <code>gh api commits/{SHA}</code>). This comes from what we learned in PR #19, where an automatic PR proposed two-stage major bumps for three actions, including <code>actions/checkout</code> v4 → v6. That showed the routine group also needs the same manual review process as <code>changesets/action</code>.</p><h2 id="release-yml-ci-gate" tabindex="-1">release.yml CI gate <a class="header-anchor" href="#release-yml-ci-gate" aria-label="Permalink to &quot;release.yml CI gate&quot;">​</a></h2><p><code>release.yml</code> runs directly on pushes to <code>main</code>, but before <code>changesets/action</code> starts, it has a CI gate that runs five steps: install → typecheck → test (core + cli) → build → consumer typecheck. If tests fail, <code>changesets/action</code> does not start and publishing does not happen. Because this repository relies primarily on local testing, it does not keep a GitHub Actions CI workflow for PRs. Before submitting a PR, developers are expected to run <code>pnpm typecheck &amp;&amp; pnpm test &amp;&amp; pnpm build</code> locally and record the results in the PR body. The test gate in the publish path is enforced by rerunning tests inside <code>release.yml</code>. Parallel validation across multiple Node versions is removed, but behavior verification remains because <code>release.yml</code> still runs typecheck / test / build before publishing. Required status checks for main branch protection are not configured in this repository (after removing <code>ci.yml</code>, statuses such as <code>test (20)</code> and <code>test (22)</code> no longer exist, so they cannot be required, and configuring them would deadlock PR merges). Instead, branch protection only enforces &quot;PR required,&quot; and if needed, you can add physical enforcement on the review path such as signed commits. The test gate is enforced in two layers: developer local runs plus the five steps in <code>release.yml</code>. Third-party app statuses such as GitGuardian Security Checks and CodeRabbit may appear, but they are not included as required checks.</p><h2 id="v0-1-0-first-publish-procedure" tabindex="-1">v0.1.0 first publish procedure <a class="header-anchor" href="#v0-1-0-first-publish-procedure" aria-label="Permalink to &quot;v0.1.0 first publish procedure&quot;">​</a></h2><p>The steps below apply to the initial publish, when the package does not yet exist on npmjs.com. From the second release onward, the normal Changesets workflow handles the process automatically, but the first publish requires user-side setup for NPM_TOKEN distribution and Trusted Publisher configuration.</p><h3 id="phase-1-—-npm-side-preparation-user-action" tabindex="-1">Phase 1 — npm-side preparation (user action) <a class="header-anchor" href="#phase-1-—-npm-side-preparation-user-action" aria-label="Permalink to &quot;Phase 1 — npm-side preparation (user action)&quot;">​</a></h3><ol><li><strong>Configure 2FA for your npm account</strong> — At <a href="https://www.npmjs.com/settings/%7Buser%7D/profile" target="_blank" rel="noreferrer">https://www.npmjs.com/settings/{user}/profile</a>, select <strong>Auth only</strong> or <strong>Auth and writes</strong>. If you use an Automation Token, publishing is possible even with Auth only.</li><li><strong>Reserve a scope (optional)</strong> — <code>@kiwa-test/dapp</code> and <code>@kiwa-test/cli</code> use the <code>@kiwa-test</code> npm organization (already created at <a href="https://www.npmjs.com/org/kiwa-test" target="_blank" rel="noreferrer">https://www.npmjs.com/org/kiwa-test</a>). If you fork kiwa and want a different scope, create your own org via <code>https://www.npmjs.com/org/create</code>.</li><li><strong>Create a Granular Access Token</strong> — Settings &gt; Access Tokens &gt; Generate New Token &gt; Granular Access Token. <ul><li>name: <code>kiwa-publish</code></li><li>expiration: 1 year (recommended)</li><li>packages: <code>@kiwa-test/*</code></li><li>permissions: <strong>Read and write</strong> (for publishing)</li><li><strong>Bypass two-factor authentication (2FA): ON</strong> (required for CI publish)</li><li>The token is shown only once immediately after creation, so you must copy it then.</li></ul></li></ol><h3 id="phase-2-—-github-side-preparation-user-action" tabindex="-1">Phase 2 — GitHub-side preparation (user action) <a class="header-anchor" href="#phase-2-—-github-side-preparation-user-action" aria-label="Permalink to &quot;Phase 2 — GitHub-side preparation (user action)&quot;">​</a></h3><ol><li><strong>Register the NPM_TOKEN secret</strong> — At <a href="https://github.com/cardene777/kiwa/settings/secrets/actions" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/settings/secrets/actions</a>, add the token from Phase 1.3 with the name <code>NPM_TOKEN</code>.</li><li><strong>Workflow permissions</strong> — In Settings &gt; Actions &gt; General, enable <strong>Read and write permissions</strong> and Allow GitHub Actions to create and approve pull requests. This allows <code>release.yml</code> to create version PRs automatically.</li><li><strong>Trusted Publishers (stronger provenance)</strong> — If you configure npm Trusted Publisher, publishing is possible without a token. In Settings &gt; Packages &gt; Trusted Publishers, specify the repo and workflow. Keep <code>permissions.id-token: write</code> in <code>release.yml</code>.</li></ol><h3 id="phase-3-—-starting-the-release-workflow-automated-path" tabindex="-1">Phase 3 — starting the release workflow (automated path) <a class="header-anchor" href="#phase-3-—-starting-the-release-workflow-automated-path" aria-label="Permalink to &quot;Phase 3 — starting the release workflow (automated path)&quot;">​</a></h3><ol><li>Create a pending changeset under <code>.changeset/</code> (<code>pnpm changeset</code>).</li><li>Merge into <code>main</code> to start <code>release.yml</code>, which automatically creates a <code>chore(release): version packages</code> PR.</li><li>Merge the version PR → <code>release.yml</code> starts again → npm publishing runs through <code>pnpm release</code>.</li><li>Because provenance is enabled, links to the source repository and build workflow appear on the package page on npmjs.com.</li></ol><h3 id="phase-4-—-post-publish-checks" tabindex="-1">Phase 4 — post-publish checks <a class="header-anchor" href="#phase-4-—-post-publish-checks" aria-label="Permalink to &quot;Phase 4 — post-publish checks&quot;">​</a></h3><ol><li><p><strong>Verify the npmjs.com pages</strong> — Check <code>https://www.npmjs.com/package/@kiwa-test/dapp</code> and <code>@kiwa-test/cli</code> for the README, provenance badge, and version <code>0.1.0</code>.</p></li><li><p><strong>smoke test</strong> — In a separate dApp project, run <code>pnpm dlx @kiwa-test/cli init</code> and confirm that the generated <code>e2e/connect.spec.ts</code> passes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/kiwa-smoke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/kiwa-smoke</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-test/cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div></li><li><p><strong>Report completion</strong> — Leave a trace on the roadmap issue.</p></li></ol><h3 id="known-risks" tabindex="-1">Known risks <a class="header-anchor" href="#known-risks" aria-label="Permalink to &quot;Known risks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Risk</th><th>Mitigation</th></tr></thead><tbody><tr><td>Package name is rejected by npm during the first publish</td><td>Open a separate issue to change the scope</td></tr><tr><td><code>NPM_TOKEN</code> is read-only and publish fails on auth</td><td>Reissue the token (change Phase 1.3 to Read and write)</td></tr><tr><td>GitHub Actions workflow permissions are read-only and version PR creation fails</td><td>Recheck Phase 2.2</td></tr><tr><td>Provenance fails on the sigstore side</td><td>Trusted Publisher is not configured; add Phase 2.3</td></tr><tr><td><code>changesets/action</code> has a compatibility issue with the pnpm v10 lockfile format</td><td>Already handled by pinning <code>release.yml</code> to pnpm version 10.33.2</td></tr></tbody></table><h2 id="related-links" tabindex="-1">Related links <a class="header-anchor" href="#related-links" aria-label="Permalink to &quot;Related links&quot;">​</a></h2><ul><li><a href="https://github.com/changesets/changesets" target="_blank" rel="noreferrer">Changesets official site</a></li><li><a href="https://github.com/changesets/action" target="_blank" rel="noreferrer">changesets/action</a></li><li><a href="https://docs.npmjs.com/generating-provenance-statements" target="_blank" rel="noreferrer">npm provenance docs</a></li><li><a href="https://docs.npmjs.com/trusted-publishers" target="_blank" rel="noreferrer">npm Trusted Publishers</a></li><li><a href="https://docs.npmjs.com/about-access-tokens#about-granular-access-tokens" target="_blank" rel="noreferrer">npm Granular Access Tokens</a></li></ul>`,33)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
